contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint _val1, uint _val2) public payable {
        uint balBefore = address(c).balance;
        c.SetMinSum(_val1); if (__ESBMC_reverted()) return;
        uint minSumAfterFirst = c.MinSum(); if (__ESBMC_reverted()) return;
        uint balAfterFirst = address(c).balance;
        c.SetMinSum(_val2); if (__ESBMC_reverted()) return;
        uint minSumAfterSecond = c.MinSum(); if (__ESBMC_reverted()) return;
        uint balAfterSecond = address(c).balance;

        assert(minSumAfterFirst == _val1 && minSumAfterSecond == _val2 && balAfterFirst == balBefore && balAfterSecond == balBefore);
    }

    receive() external payable {}
}

