pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {PRIVATE_ETH_CELL} from "../src/PRIVATE_ETH_CELL.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    PRIVATE_ETH_CELL c;

    function setUp() public {
        c = new PRIVATE_ETH_CELL();
    }

    function _run(uint256 _val1, uint256 _val2) internal {
        uint balBefore = address(c).balance;
        try c.SetMinSum(_val1) {} catch { return; }
        uint256 minSumAfterFirst;
        try c.MinSum() returns (uint256 __r) { minSumAfterFirst = __r; } catch { return; }
        uint balAfterFirst = address(c).balance;
        try c.SetMinSum(_val2) {} catch { return; }
        uint256 minSumAfterSecond;
        try c.MinSum() returns (uint256 __r) { minSumAfterSecond = __r; } catch { return; }
        uint balAfterSecond = address(c).balance;
        assertTrue(minSumAfterFirst == _val1 && minSumAfterSecond == _val2 && balAfterFirst == balBefore && balAfterSecond == balBefore);
    }

    function testFuzz_run(uint256 _val1, uint256 _val2) public {
        _run(_val1, _val2);
    }

    receive() external payable {}
}
